71	impl EngineHandle {
72	    pub fn new(submit_tx: mpsc::UnboundedSender<SubmittedRequest>) -> Self {
73	        Self::from_parts(vec![submit_tx], Vec::new())
74	    }
75	
76	    /// Construct a handle that owns the engine thread shutdown.
77	    ///
78	    /// Dropping the last handle clone closes the submit channel and then waits
79	    /// for the thread to return. That final drop may block until in-flight
80	    /// generation and backend teardown finish.
81	    pub fn new_with_join_handle(
82	        submit_tx: mpsc::UnboundedSender<SubmittedRequest>,
83	        join_handle: JoinHandle<()>,
84	    ) -> Self {
85	        Self::from_parts(vec![submit_tx], vec![join_handle])
86	    }
87	
88	    /// Construct a multi-partition handle: one submit channel and one owned
89	    /// engine thread per logical scheduler partition (e.g. one autonomous
90	    /// engine per DP rank). [`Self::submit`] routes by the request's
91	    /// `data_parallel_rank`; unbound requests go to the least-loaded
92	    /// partition (waiting requests weigh 4x, the vLLM DP policy).
93	    ///
94	    /// Dropping the last handle clone closes every channel and joins every
95	    /// thread in partition order.
96	    pub fn new_with_join_handles(
97	        submit_txs: Vec<mpsc::UnboundedSender<SubmittedRequest>>,
98	        join_handles: Vec<JoinHandle<()>>,
99	    ) -> Self {
100	        assert!(
101	            !submit_txs.is_empty(),
102	            "an engine must expose at least one scheduler partition"
103	        );
104	        Self::from_parts(submit_txs, join_handles)
105	    }
106	
107	    fn from_parts(
108	        submit_txs: Vec<mpsc::UnboundedSender<SubmittedRequest>>,
109	        join_handles: Vec<JoinHandle<()>>,
110	    ) -> Self {
111	        Self {
112	            inner: Arc::new(EngineInner {
113	                submit_txs,
114	                join_handles,
115	            }),
116	            servable_len: None,
117	            kv_capacity: None,
118	            metrics_watches: vec![None],
119	        }
120	    }
