122	    #[must_use]
123	    pub fn with_servable_len(mut self, servable_len: u32) -> Self {
124	        self.servable_len = Some(servable_len);
125	        self
126	    }
127	
128	    pub fn servable_len(&self) -> Option<u32> {
129	        self.servable_len
130	    }
131	
132	    #[must_use]
133	    pub fn with_kv_capacity(mut self, kv_capacity: KvCapacity) -> Self {
134	        self.kv_capacity = Some(kv_capacity);
135	        self
136	    }
