138	    /// KV pool capacity, if the engine reported it. A batch whose per-request
139	    /// block footprint exceeds [`KvCapacity::total_blocks`] cannot be resident
140	    /// at once.
141	    pub(crate) fn kv_capacity(&self) -> Option<KvCapacity> {
142	        self.kv_capacity
143	    }
144	
145	    #[must_use]
146	    pub fn with_metrics_watch(mut self, metrics_watch: watch::Receiver<SchedulerMetrics>) -> Self {
147	        self.metrics_watches = vec![Some(metrics_watch)];
148	        self
149	    }
150	
151	    /// Attach one load feed per logical scheduler partition.
152	    ///
153	    /// The vector is also the engine's frontend-visible DP topology, so an
154	    /// empty vector is an invalid engine rather than a single partition with
155	    /// missing metrics.
156	    #[must_use]
157	    pub fn with_metrics_watches(
158	        mut self,
159	        metrics_watches: Vec<watch::Receiver<SchedulerMetrics>>,
160	    ) -> Self {
161	        assert!(
162	            !metrics_watches.is_empty(),
163	            "an engine must expose at least one scheduler partition"
164	        );
165	        self.metrics_watches = metrics_watches.into_iter().map(Some).collect();
166	        self
167	    }
168	
169	    /// Number of logical scheduler partitions exposed to the frontend.
170	    pub(crate) fn scheduler_partition_count(&self) -> usize {
171	        self.metrics_watches.len()
172	    }
173	
174	    /// A receiver for one partition's live load, if it wired one. Awaiting
175	    /// [`watch::Receiver::changed`] wakes once per scheduler step under load and
176	    /// stays quiet when idle, so a consumer republishes on real change rather
177	    /// than polling. `None` if the partition does not report a load feed or the
178	    /// index is outside the engine topology.
179	    pub(crate) fn metrics_watch_for(
180	        &self,
181	        partition: usize,
182	    ) -> Option<watch::Receiver<SchedulerMetrics>> {
183	        self.metrics_watches.get(partition)?.clone()
184	    }
185	
186	    /// Single-partition compatibility accessor.
187	    pub fn metrics_watch(&self) -> Option<watch::Receiver<SchedulerMetrics>> {
188	        self.metrics_watch_for(0)
189	    }
190	
191	    /// Submit an unresolved request: no KV-prefix resolution ran for it, so
192	    /// the scheduler receives [`KvPrefix::none`] and prefills from its own
193	    /// GPU prefix match alone. See [`Self::submit_resolved`].
194	    #[allow(clippy::result_large_err)]
195	    pub fn submit(
196	        &self,
197	        req: GenerateRequest,
198	    ) -> std::result::Result<(), mpsc::error::SendError<GenerateRequest>> {
199	        self.submit_resolved(req, KvPrefix::none())
200	    }
201	
202	    /// Submit a request together with its KV-prefix resolution. Routing is by
203	    /// the request's `data_parallel_rank` (unbound requests go to the
204	    /// least-loaded partition), so the caller that resolved the prefix must
205	    /// have bound the request to the rank it resolved against.
206	    #[allow(clippy::result_large_err)]
207	    fn submit_resolved(
208	        &self,
209	        req: GenerateRequest,
210	        kv_prefix: KvPrefix,
211	    ) -> std::result::Result<(), mpsc::error::SendError<GenerateRequest>> {
212	        // A resolved prefix binds the request: its hold pins blocks on
213	        // the rank it resolved against, so that rank wins the routing.
214	        // A caller-bound rank that disagrees is a caller bug.
215	        let partition = match (kv_prefix.rank(), req.data_parallel_rank) {
216	            (Some(resolved), bound) => {
217	                debug_assert!(
218	                    bound.is_none_or(|b| b == resolved),
219	                    "request bound to rank {bound:?} but its prefix resolved on rank {resolved}"
220	                );
221	                resolved
222	            }
223	            (None, Some(bound)) => bound,
224	            (None, None) => self.least_loaded_partition(),
225	        };
226	        if let Some(submit_tx) = self.inner.submit_txs.get(partition) {
227	            return submit_tx
228	                .send((req, kv_prefix))
229	                .map_err(|err| mpsc::error::SendError(err.0.0));
230	        }
231	        // An out-of-range rank is a caller error, not an engine
232	        // failure: answer the request with the standard
233	        // Scheduled → Rejected pair instead of failing the submit.
234	        reject_unroutable(&req, partition, self.inner.submit_txs.len());
235	        Ok(())
236	    }
237	
238	    /// Placement for an unbound request: the partition with the lowest
239	    /// waiting-weighted load (`running + 4 × waiting`, the same weight the
240	    /// vLLM DP load balancer uses), ties to the lowest index. Scores come
241	    /// from the partitions' load watches; a partition without a feed scores
242	    /// zero, so the single-partition degenerate always returns 0.
243	    fn least_loaded_partition(&self) -> usize {
244	        self.inner
245	            .submit_txs
246	            .iter()
247	            .enumerate()
248	            .min_by_key(|(partition, _)| {
249	                let score = self
250	                    .metrics_watches
251	                    .get(*partition)
252	                    .and_then(Option::as_ref)
253	                    .map_or(0, |watch| {
254	                        let snapshot = watch.borrow();
255	                        snapshot.num_running_reqs + 4 * snapshot.num_waiting_reqs
256	                    });
257	                (score, *partition)
258	            })
259	            .map_or(0, |(partition, _)| partition)
260	    }
261	}
