263	pub fn panic_message(payload: &dyn Any) -> &str {
264	    payload
265	        .downcast_ref::<&str>()
266	        .copied()
267	        .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
268	        .unwrap_or("<non-string panic payload>")
269	}
